import shutil; os.makedirs('./_sandbox/phaseV/t3/working/code', exist_ok=True); shutil.copytree('./_sandbox/ext/vec2vec', './_sandbox/phaseV/t3/working/vec2vec', dirs_exist_ok=True)

# Cell 2 - settings. CHANGE ONLY THESE TWO LINES.
FRIEND = 1            # 1, 2, 3, 4 or 5 (Aman tells you which)
QUICK_TEST = True    # True = 10-minute check on a tiny subset; False = the real 10.5-hour run

# The sweep. Each friend runs two lines, one per GPU. (The workstation runs ours fp32 seeds 7 and 8.)
SWEEP = {
    1: [dict(kind="ours", seed=5), dict(kind="ours", seed=1)],
    2: [dict(kind="ours", seed=2), dict(kind="ours", seed=3)],
    3: [dict(kind="ours", seed=4), dict(kind="ours", seed=6)],
    4: [dict(kind="dpr_matched", seed=5), dict(kind="dpr_matched", seed=1)],
    5: [dict(kind="native", seed=5, num_points=1_000_000), dict(kind="native", seed=5, num_points=50_000)],
}
BUDGET_HOURS = {"ours": 10.5, "dpr_matched": 10.5, "native": 10.0}   # native epochs are long; keep room under 12 h

import os, sys, json, time, glob, subprocess
import numpy as np, torch
assert True or torch.cuda.device_count() == 2, "Set Accelerator = GPU T4 x2 (two GPUs), then restart"
RUNS = []
for spec in SWEEP[FRIEND]:
    name = spec["kind"] + (f"{spec['num_points'] // 1000}k" if spec["kind"] == "native" else "")
    name += f"_fp32_s{spec['seed']}" if spec["kind"] == "ours" else f"_s{spec['seed']}"
    RUNS.append({**spec, "name": name + ("_quicktest" if QUICK_TEST else "")})
for gpu, r in enumerate(RUNS):
    print(f"GPU {gpu}: {r['name']}   budget {0.05 if QUICK_TEST else BUDGET_HOURS[r['kind']]} h")

# Cell 3 - what we expect BEFORE the run (written down so the result cannot move the goalposts)
EXPECT = {
    "random guess": "top-1 = 1/8,192 = 0.00012, average rank = 4,096 (ours / dpr_matched); "
                    "authors' top-1 within 1,024 = 0.001 (native)",
    "steps per epoch": "ours 195, dpr_matched 390, native-1M 3,906, native-50k 195 (batch 256)",
    "minutes per epoch on a T4": "ours about 0.7-2 (unknown before this run; the workstation needed 0.66 with two "
                                 "runs sharing a faster GPU); native much longer because it also runs two text encoders",
    "training steps in 10.5 h": "ours roughly 60,000-180,000. Our first run had only 19,000. The paper reports seeds "
                                "that converged within 10 epochs of 1M points, about 39,000 steps",
    "LEARNED (ours, dpr_matched)": "top-1 >= 0.01 (80x random) OR average rank <= a quarter of random (1,024 of 8,192) at any epoch",
    "LEARNED (native)": "authors' validation top-1 (within 1,024) >= 0.1 at any epoch",
    "chance that at least one of our 8 seeds learns (6 here + 2 on the workstation)": "unknown. If each seed had the paper's cross-backbone rate "
        "(e5->gtr: 3 of 15 seeds), about 1 - 0.8^8 = 0.83. The paper also reports gte->gtr failing without "
        "per-pair tuning, so zero is a real possibility and would itself be a result",
    "native-1M (positive control)": "should learn: it is the authors' own pair and pipeline. If it does not, the budget "
                                    "per run is too short and a failure of our pair is inconclusive",
    "native-50k vs native-1M": "if 1M learns and 50k does not, too little data is the problem (Aman's hypothesis)",
    "dpr_matched vs ours": "if dpr_matched learns and ours does not, more / matched victim-side data helps",
}
for k, v in EXPECT.items(): print(f"- {k}: {v}")

open('./_sandbox/phaseV/t3/working/code/v2v_runner.py','w').write('"""Run the OFFICIAL vec2vec trainer (github.com/rjha18/vec2vec, commit 5efb3c0).\n\nTwo modes:\n  * precomputed (default): the trainer gets OUR saved vectors through its own "precomputed embeddings"\n    path (the one the authors use for fMRI data). Victim side = BGE vectors (fp32 or decoded compressed),\n    attacker side = GTR vectors. No pairs are given to training.\n  * native=True: the authors\' own text pipeline and default model pair from configs/unsupervised.toml\n    (positive control: does vec2vec learn at all on this machine in this time?).\n\nWhat is changed in the authors\' code, and nothing else:\n  1. Data input (precomputed mode only) and per-space encoder sizes (ours are 1024 and 768).\n  2. A wall-clock budget (training time, summed over resumed sessions) instead of the epoch limit.\n  3. Optional: early stopping switched off. Their rule (min 80 epochs, patience 20) counts epochs and was\n     calibrated for 1M-vector epochs (~3,900 steps); our epochs are ~195 steps, so it stopped run 1 after\n     ~6% of the paper\'s minimum training.\n  4. After every epoch (precomputed mode) we score with OUR metric, same as mini-vec2vec: top-1, average\n     rank and mean cosine of translated victim vectors vs their true GTR vectors (true vectors used only here).\n  5. Full checkpoints (translator, all discriminators, all optimisers and schedulers, random states) every\n     30 minutes and at the end, so a run can be resumed on another machine or session.\n  6. wandb logging replaced by a local JSON-lines log.\nAll losses, architecture, optimisers and hyper-parameters come from the authors\' configs/unsupervised.toml\nunless the caller overrides them explicitly through extra_args (and then they are written in the log).\n"""\nimport os, sys, json, time, types, inspect\n\ndef run(repo_dir, X_victim, Y_attacker, X_eval, Y_eval, out_dir, budget_hours,\n        seed=5, val_size=4096, extra_args=None, log=print,\n        native=False, early_stopping=True, resume_from=None, ckpt_every_minutes=30):\n    import numpy as np, torch\n    t_start = time.time()\n    out_dir = os.path.abspath(out_dir)\n    resume_from = os.path.abspath(resume_from) if resume_from else None\n    repo_dir = os.path.abspath(repo_dir)\n    os.makedirs(out_dir, exist_ok=True)\n    sys.path.insert(0, repo_dir)\n    os.chdir(repo_dir)\n\n    # beir is only used by dataset paths we do not use; stub it so it need not be installed\n    if "beir" not in sys.modules:\n        for name in ["beir", "beir.datasets", "beir.datasets.data_loader_hf"]:\n            sys.modules[name] = types.ModuleType(name)\n        sys.modules["beir.datasets.data_loader_hf"].HFDataLoader = object\n\n    # Windows: vec2text imports the Unix-only "resource" module; give it a harmless stand-in\n    if os.name == "nt" and "resource" not in sys.modules:\n        try:\n            import resource  # noqa: F401  (already provided, e.g. by a shim)\n        except ImportError:\n            stub = types.ModuleType("resource")\n            stub.RLIMIT_NOFILE = 7\n            stub.getrlimit = lambda *_: (8192, 8192)\n            stub.setrlimit = lambda *_: None\n            sys.modules["resource"] = stub\n\n    import wandb\n    import train as T\n    from fmri.data import FmriSingleViewDataset\n\n    # Windows: data-loader worker processes use "spawn" and would have to copy the whole dataset;\n    # their helper also uses a Linux-only call. Load data in the main process instead.\n    if os.name == "nt":\n        T.get_num_proc = lambda: 0\n    if not torch.cuda.is_available():          # their helper divides by the GPU count (CPU-only test runs)\n        T.get_num_proc = lambda: 2\n\n    # -- resume metadata (states are loaded into the live objects at the first epoch)\n    ckpt = None\n    if resume_from:\n        ckpt = torch.load(resume_from, map_location="cpu", weights_only=False)\n        log(f"resuming from {resume_from}: epoch {ckpt[\'epoch\']}, {ckpt[\'train_hours\']:.2f} training hours so far")\n\n    # -- 6. local logging instead of wandb\n    log_path = os.path.join(out_dir, "v2v_log.jsonl")\n    def _append(path, rec):\n        with open(path, "a") as f:\n            f.write(json.dumps(rec) + "\\n")\n    def _wandb_log(d, *a, **k):\n        rec = {"t_hours": (time.time() - t_start) / 3600, "train_hours": _train_hours()}\n        for key, v in d.items():\n            if isinstance(v, (int, float)):\n                rec[key] = float(v)\n        _safe(lambda: _append(log_path, {"kind": "authors_val", **rec}), "v2v_log.jsonl")\n    wandb.log = _wandb_log\n    wandb.Image = lambda *a, **k: None\n\n    # -- 2. training-time budget, summed over resumed sessions; at least one epoch always runs\n    clock = {"t0": None, "offset": ckpt["train_hours"] if ckpt else 0.0}\n    def _train_hours():\n        return clock["offset"] + (0.0 if clock["t0"] is None else (time.time() - clock["t0"]) / 3600)\n    def _time_up():\n        if clock["t0"] is None:\n            clock["t0"] = time.time()\n            return False\n        return _train_hours() > budget_hours\n\n    # -- 1. our data through the precomputed path\n    if not native:\n        Xv = torch.tensor(np.asarray(X_victim, dtype=np.float32))\n        Ya = torch.tensor(np.asarray(Y_attacker, dtype=np.float32))\n        Xe = torch.tensor(np.asarray(X_eval, dtype=np.float32))\n        Ye = torch.tensor(np.asarray(Y_eval, dtype=np.float32))\n\n        class PairedDifferentSizes(torch.utils.data.Dataset):\n            """Same as the authors\' FmriPairedDataset, but the two spaces may have different sizes."""\n            def __init__(self, name_a, Za, name_b, Zb):\n                assert len(Za) == len(Zb)\n                self.a, self.Za, self.b, self.Zb = name_a, Za, name_b, Zb\n            def __len__(self):\n                return len(self.Za)\n            def __getitem__(self, i):\n                return {self.a: self.Za[i], self.b: self.Zb[i]}\n\n        def _loader(*a, **k):\n            supset = FmriSingleViewDataset("gtr", Ya)          # attacker\'s own space ("supervised" = known model)\n            unsupset = FmriSingleViewDataset("bge", Xv)        # stolen victim vectors ("unsupervised" = unknown)\n            n = min(val_size, len(Xe))\n            val = PairedDifferentSizes("gtr", Ye[:n], "bge", Xe[:n])\n            return supset, unsupset, val, {"gtr": Ya.shape[1], "bge": Xv.shape[1]}\n        T.load_fmri_train_and_eval_datasets = _loader\n        Xe_n = torch.nn.functional.normalize(Xe, dim=1)\n        Ye_n = torch.nn.functional.normalize(Ye, dim=1)\n\n    # -- 4. our metric after every epoch\n    def _score(translator):\n        dev = next(translator.parameters()).device\n        was_training = translator.training\n        translator.eval()\n        outs = []\n        with torch.no_grad():\n            for i in range(0, len(Xe_n), 1024):\n                ins = {"bge": Xe_n[i:i+1024].to(dev), "gtr": Ye_n[i:i+1024].to(dev)}\n                _, tr = translator(ins, include_reps=False)\n                outs.append(tr["gtr"]["bge"].float().cpu())\n        if was_training:\n            translator.train()\n        Z = torch.nn.functional.normalize(torch.cat(outs), dim=1)\n        S = Z @ Ye_n.T\n        dg = S.diag()\n        ranks = (S > dg[:, None]).sum(1) + 1\n        return {"top1": float((ranks == 1).float().mean()), "avg_rank": float(ranks.float().mean()),\n                "mean_cos": float(dg.mean())}\n\n    # -- 5. full checkpoints\n    def _safe(fn, what, tries=6):\n        """Saving must never kill a multi-day run: on Windows a backup program reading the file can block\n        overwriting it for a moment. Retry, then log and carry on (the next save will try again)."""\n        for i in range(tries):\n            try:\n                fn(); return True\n            except OSError as err:\n                if i == tries - 1:\n                    log(f"WARNING: could not write {what} ({err}); training continues, will retry at the next save")\n                    return False\n                time.sleep(5)\n    GAN_NAMES = ["gan", "sup_gan", "latent_gan", "similarity_gan"]\n    def _sd(x):\n        return x.state_dict() if x is not None and hasattr(x, "state_dict") else None\n    def _save_ckpt(k):\n        acc = k["accelerator"]\n        blob = {"epoch": state["epoch"], "train_hours": _train_hours(), "best": dict(best),\n                "translator": acc.unwrap_model(k["translator"]).state_dict(),\n                "gen_optimizers": [o.state_dict() for o in k["gen_optimizers"]],\n                "gen_schedulers": [s.state_dict() for s in k["gen_schedulers"]],\n                "gans": {n: {"disc": _sd(acc.unwrap_model(getattr(k[n], "discriminator", None))\n                                         if getattr(k[n], "discriminator", None) is not None else None),\n                             "opt": _sd(getattr(k[n], "discriminator_opt", None)),\n                             "sched": _sd(getattr(k[n], "discriminator_scheduler", None))}\n                         for n in GAN_NAMES if k.get(n) is not None},\n                "scaler": _sd(getattr(acc, "scaler", None)),\n                "rng": {"torch": torch.get_rng_state(),\n                        "cuda": torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None,\n                        "numpy": np.random.get_state()},\n                "args": args}\n        tmp = os.path.join(out_dir, "resume.pt.tmp")\n        ok = _safe(lambda: torch.save(blob, tmp), "resume.pt.tmp") and \\\n             _safe(lambda: os.replace(tmp, os.path.join(out_dir, "resume.pt")), "resume.pt")  # never half-written\n        state["last_ckpt"] = time.time()\n        if ok:\n            log(f"checkpoint saved at epoch {state[\'epoch\']} ({_train_hours():.2f} training hours)")\n    def _load_ckpt(k):\n        acc = k["accelerator"]\n        acc.unwrap_model(k["translator"]).load_state_dict(ckpt["translator"])\n        for o, sd in zip(k["gen_optimizers"], ckpt["gen_optimizers"]): o.load_state_dict(sd)\n        for s, sd in zip(k["gen_schedulers"], ckpt["gen_schedulers"]): s.load_state_dict(sd)\n        for n, g in ckpt["gans"].items():\n            obj = k.get(n)\n            if obj is None: continue\n            if g["disc"] is not None: acc.unwrap_model(obj.discriminator).load_state_dict(g["disc"])\n            if g["opt"] is not None: obj.discriminator_opt.load_state_dict(g["opt"])\n            if g["sched"] is not None: obj.discriminator_scheduler.load_state_dict(g["sched"])\n        if ckpt.get("scaler") is not None and getattr(acc, "scaler", None) is not None:\n            acc.scaler.load_state_dict(ckpt["scaler"])\n        torch.set_rng_state(ckpt["rng"]["torch"])\n        if ckpt["rng"]["cuda"] is not None and torch.cuda.is_available():\n            torch.cuda.set_rng_state_all(ckpt["rng"]["cuda"])\n        np.random.set_state(ckpt["rng"]["numpy"])\n        log("resume: all model, optimiser and scheduler states loaded")\n\n    best = dict(ckpt["best"]) if ckpt else {"top1": -1.0}\n    state = {"epoch": ckpt["epoch"] if ckpt else 0, "loaded": ckpt is None, "last_ckpt": time.time()}\n    orig_loop = T.training_loop_\n    def _loop(*a, **k):\n        if not state["loaded"]:\n            _load_ckpt(k); state["loaded"] = True\n        t0 = time.time()\n        r = orig_loop(*a, **k)\n        state["epoch"] += 1\n        rec = {"kind": "ours", "epoch": state["epoch"], "t_hours": (time.time() - t_start) / 3600,\n               "train_hours": _train_hours(), "epoch_minutes": (time.time() - t0) / 60}\n        if not native:\n            sc = _score(k["translator"])\n            rec.update(sc)\n        _safe(lambda: _append(log_path, rec), "v2v_log.jsonl")\n        log(json.dumps(rec))\n        model = k["accelerator"].unwrap_model(k["translator"])\n        _safe(lambda: torch.save(model.state_dict(), os.path.join(out_dir, "translator_latest.pt")), "translator_latest.pt")\n        if not native and sc["top1"] > best["top1"]:\n            best.update(sc, epoch=state["epoch"])\n            _safe(lambda: torch.save(model.state_dict(), os.path.join(out_dir, "translator_best.pt")), "translator_best.pt")\n            _safe(lambda: json.dump(best, open(os.path.join(out_dir, "best.json"), "w")), "best.json")\n        if (time.time() - state["last_ckpt"]) / 60 >= ckpt_every_minutes or _train_hours() > budget_hours:\n            _save_ckpt(k)\n        return r\n    T.training_loop_ = _loop\n\n    # -- patch main(): per-space encoder sizes, time budget, drop_last flag, logging call\n    src = inspect.getsource(T.main)\n    a = "encoder_dims = {cfg.sup_emb: int(embed_dim), cfg.unsup_emb: int(embed_dim)}"\n    b = "encoder_dims = {cfg.sup_emb: int(embed_dim[cfg.sup_emb]), cfg.unsup_emb: int(embed_dim[cfg.unsup_emb])}"\n    c = "    for epoch in range(max_num_epochs):\\n"\n    d = c + "        if _TIME_UP():\\n            print(\'Time budget reached, stopping.\')\\n            break\\n"\n    e = "drop_last=cfg.train_drop_last if hasattr(cfg, \'train_drop_last\') else not fmri_mode"\n    f_ = "drop_last=bool(cfg.train_drop_last) if hasattr(cfg, \'train_drop_last\') else not fmri_mode"\n    g = "wandb.log(val_res)"   # wandb.init() re-binds wandb.log, so route the call explicitly\n    assert src.count(a) == 1 and src.count(c) == 1 and src.count(e) == 2 and src.count(g) == 1, \\\n        "vec2vec code changed: patch points not found"\n    src = src.replace(a, b).replace(c, d).replace(e, f_).replace(g, "_WANDB_LOG(val_res)")\n    T.__dict__["_WANDB_LOG"] = _wandb_log\n    T.__dict__["_TIME_UP"] = _time_up\n    exec(compile(src, T.__file__, "exec"), T.__dict__)\n\n    if native:\n        args = {"epochs": 100000, "use_wandb": 0, "seed": seed,\n                "save_dir": out_dir.rstrip("/\\\\") + "/authors_{}/", "force_wandb_name": 1, "wandb_name": "run"}\n    else:\n        args = {"unsup_emb": "bge", "sup_emb": "gtr", "dataset": "fmri_precomputed", "epochs": 100000,\n                "use_wandb": 0, "seed": seed, "val_size": val_size,\n                "save_dir": out_dir.rstrip("/\\\\") + "/authors_{}/", "force_wandb_name": 1, "wandb_name": "run",\n                # our two sides have different sizes: drop the last partial batch so every step pairs two\n                # full batches, as the authors\' text path does by default\n                "train_drop_last": 1}\n    if not early_stopping:\n        args["min_epochs"] = 10 ** 9      # their early-stopping check only starts after min_epochs\n    args.update(extra_args or {})\n    if ckpt is not None:   # a resumed run must be the same experiment\n        old = {k: v for k, v in ckpt["args"].items() if k != "save_dir"}\n        new = {k: v for k, v in args.items() if k != "save_dir"}\n        assert old == new, f"resume: settings differ from the checkpoint\\n old {old}\\n new {new}"\n    with open(log_path, "a") as f:\n        f.write(json.dumps({"kind": "run_args", "native": native, "early_stopping": early_stopping,\n                            "resume_from": resume_from, "budget_hours": budget_hours, **args}) + "\\n")\n    argv = ["train.py", "unsupervised"]\n    for k_, v_ in args.items():\n        argv += [f"--{k_}", str(v_)]\n    sys.argv = argv\n    T.argv = argv\n    T.main()\n    return best, log_path')

open('./_sandbox/phaseV/t3/working/code/v2v_job.py','w').write('"""One vec2vec run (one variant, one seed). Used by the Kaggle sweep notebook (two of these at once, one per T4)\nand by the workstation (to continue the winning run from its checkpoint). Neural Nexus vector-DB project.\n\nKinds:\n  ours         victim = 50k BGE-large vectors (fp32 or decoded compressed), attacker = 200k A2 GTR vectors.\n               This is the experiment of the paper.\n  dpr_matched  data diagnostic: victim side = BGE-large of A2 texts 0-99,999 (embedded here), attacker side =\n               GTR of A2 texts 100,000-199,999. Twice the victim-side data, both sides from the same text pool.\n               Scored on the same 8,192 victim passages as "ours".\n  native       positive control: the authors\' own pair (stella -> gte) and own NQ text pipeline, num_points per side.\n               Scored only with the authors\' validation metrics (their 4,096 held-out NQ passages).\n\nUsage:\n  python v2v_job.py --kind ours --scheme fp32 --seed 5 --hours 10.5 --data /kaggle/input --out runs/ours_s5 --repo vec2vec\n  python v2v_job.py ... --resume runs/ours_s5/resume.pt --hours 60      (continue: --hours is the new TOTAL budget)\n"""\nimport os, sys, json, time, glob, argparse, platform\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\np = argparse.ArgumentParser()\np.add_argument("--kind", required=True, choices=["ours", "dpr_matched", "native"])\np.add_argument("--scheme", default="fp32", help="ours only: fp32 or a Phase B scheme such as pq128x8")\np.add_argument("--seed", type=int, required=True)\np.add_argument("--hours", type=float, required=True, help="total training-time budget (summed over resumed sessions)")\np.add_argument("--data", required=True, help="folder searched (recursively) for the input files")\np.add_argument("--out", required=True)\np.add_argument("--repo", required=True, help="clone of github.com/rjha18/vec2vec at commit 5efb3c0")\np.add_argument("--resume", default=None, help="resume.pt from an earlier session of THE SAME run")\np.add_argument("--num_points", type=int, default=1_000_000, help="native only: texts per side")\np.add_argument("--early_stopping", type=int, default=0, help="1 = keep the authors\' rule (min 80 epochs, patience 20)")\np.add_argument("--smoke", action="store_true", help="tiny subset, to test the setup")\na = p.parse_args()\n\nimport numpy as np, torch\nfrom v2v_runner import run\n\nOUT = os.path.abspath(a.out)\nos.makedirs(OUT, exist_ok=True)\nREPO = os.path.abspath(a.repo)\nif os.name == "nt":   # keep Windows awake while this process runs (no admin rights needed)\n    import ctypes\n    ctypes.windll.kernel32.SetThreadExecutionState(0x80000000 | 0x00000001)\n\nL, MODEL, EVAL_N = 32, "bge-large", 8192\ngpu = torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu"\nprint(f"kind={a.kind} scheme={a.scheme} seed={a.seed} gpu={gpu} budget={a.hours}h out={OUT}", flush=True)\nassert torch.cuda.is_available() or a.smoke, "No CUDA GPU visible to PyTorch"\n\ndef find_one(name):\n    hits = sorted(set(glob.glob(os.path.join(a.data, "**", name), recursive=True)))\n    assert len(hits) >= 1, f"input file {name} not found under {a.data}"\n    if len(hits) > 1:   # the same file can be attached through two notebooks; it must be identical\n        sizes = {os.path.getsize(h) for h in hits}\n        assert len(sizes) == 1, f"{name}: several different copies found: {hits}"\n    return hits[0]\n\n@torch.no_grad()\ndef embed_bge(texts, bs=128):\n    """Identical to Phase A (build_A.py cell 4): fp16 BGE-large, CLS token, L2-normalised, no prefix for passages."""\n    from transformers import AutoModel, AutoTokenizer\n    tok = AutoTokenizer.from_pretrained("BAAI/bge-large-en-v1.5")\n    m = AutoModel.from_pretrained("BAAI/bge-large-en-v1.5", torch_dtype=torch.float16).to("cuda").eval()\n    out = []\n    for i in range(0, len(texts), bs):\n        b = tok(texts[i:i + bs], padding=True, truncation=True, max_length=512, return_tensors="pt").to("cuda")\n        h = m(**b).last_hidden_state[:, 0]\n        out.append(torch.nn.functional.normalize(h.float(), dim=-1).cpu())\n    del m; torch.cuda.empty_cache()\n    return torch.cat(out).numpy().astype(np.float32)\n\nextra = {} if torch.cuda.is_available() else {"mixed_precision": "no"}\ninfo = {}\nif a.kind in ("ours", "dpr_matched"):\n    Y_true = np.load(find_one(f"gtr_victim_L{L}.npy")).astype(np.float32)          # scoring only\n    X_vic_fp32 = np.load(find_one(f"{MODEL}_victim_L{L}.npy")).astype(np.float32)\n    assert X_vic_fp32.shape == (50000, 1024) and Y_true.shape == (50000, 768)\n    eval_idx = np.random.default_rng(0).choice(50000, EVAL_N, replace=False)       # same 8,192 as every phase\n    Y_att_all = np.load(find_one(f"gtr_attextra_L{L}.npy")).astype(np.float32)\n    assert Y_att_all.shape == (200000, 768) and np.isfinite(Y_att_all).all()\n    if a.kind == "ours":\n        X_train = X_vic_fp32 if a.scheme == "fp32" else \\\n            np.load(find_one(f"decoded_victim_{a.scheme}_{MODEL}_L{L}.npy")).astype(np.float32)\n        assert X_train.shape == (50000, 1024) and np.isfinite(X_train).all()\n        X_eval = X_train[eval_idx]\n        Y_train = Y_att_all\n    else:\n        cache = os.path.join(OUT, f"bge-large_attextra0-100k_L{L}.npy")\n        if os.path.exists(cache):\n            X_train = np.load(cache)\n        else:\n            texts = json.load(open(find_one("texts_extra.json")))[f"extra_p_L{L}"]\n            assert len(texts) == 200000\n            t = time.time(); X_train = embed_bge(texts[:100000]); np.save(cache, X_train)\n            print(f"embedded 100,000 A2 texts with BGE-large in {time.time() - t:.0f}s", flush=True)\n        assert X_train.shape == (100000, 1024) and abs(np.linalg.norm(X_train, axis=1).mean() - 1) < 1e-3\n        Y_train = Y_att_all[100000:]                  # other texts: the two sides share no passage\n        X_eval = X_vic_fp32[eval_idx]\n    Y_eval = Y_true[eval_idx]\n    del Y_true, X_vic_fp32, Y_att_all            # keep only what training needs (two runs share the machine\'s RAM)\n    X_train, Y_train = [z.copy() if z.base is not None else z for z in (X_train, Y_train)]  # drop views of big arrays\n    if a.smoke:\n        X_train, Y_train, X_eval, Y_eval = X_train[:5000], Y_train[:20000], X_eval[:1024], Y_eval[:1024]\n        extra.update({"val_bs": 512, "top_k_size": 512, "top_k_batches": 2})\n    info = {"n_victim_side": len(X_train), "n_attacker_side": len(Y_train), "n_eval": len(X_eval),\n            "steps_per_epoch": len(X_train) // 256}\n    print(json.dumps(info), flush=True)\n    native = False\nelse:\n    X_train = Y_train = X_eval = Y_eval = None\n    extra.update({"num_points": 2000 if a.smoke else a.num_points})\n    if a.smoke:\n        extra.update({"val_size": 512, "val_bs": 256, "top_k_size": 256, "top_k_batches": 2})\n    info = {"num_points_per_side": extra["num_points"], "steps_per_epoch": extra["num_points"] // 256}\n    native = True\n\nt0 = time.time()\nbest, log_path = run(REPO, X_train, Y_train, X_eval, Y_eval, OUT, budget_hours=a.hours, seed=a.seed,\n                     val_size=min(4096, len(X_eval)) if X_eval is not None else 4096,\n                     extra_args=extra, log=lambda s: print(s, flush=True), native=native,\n                     early_stopping=bool(a.early_stopping), resume_from=a.resume)\nos.chdir(HERE)\n\n# ---- summary + plot\nrows = [json.loads(l) for l in open(log_path)]\nours = [r for r in rows if r["kind"] == "ours"]\nval = [r for r in rows if r["kind"] == "authors_val"]\ndef authors_top1(r):\n    """Authors\' top-1 (within batches of top_k_size = 1,024 candidates, averaged over top_k_batches) for the\n    unknown -> known direction: the victim ("unsupervised") space translated into the attacker\'s space."""\n    unsup, sup = ("stella", "gte") if native else ("bge", "gtr")\n    keys = [k for k in r if k.startswith(f"val/{unsup}_{sup}_top_1_acc")]\n    return max((r[k] for k in keys), default=float("nan"))\nsummary = {"kind": a.kind, "scheme": a.scheme, "seed": a.seed, "budget_hours": a.hours, "smoke_test": a.smoke,\n           "resumed_from": a.resume, "machine": platform.node(), "gpu": gpu, "torch": torch.__version__, **info,\n           "train_hours": ours[-1]["train_hours"], "epochs": ours[-1]["epoch"],\n           "steps": ours[-1]["epoch"] * info["steps_per_epoch"],\n           "minutes_per_epoch_median": float(np.median([r["epoch_minutes"] for r in ours])),\n           "authors_val_top1_last": authors_top1(val[-1]) if val else None,\n           "authors_val_top1_max": max(authors_top1(r) for r in val) if val else None}\nif not native:\n    summary.update({"final": {k: ours[-1][k] for k in ["top1", "avg_rank", "mean_cos"]},\n                    "best_by_true_pairs": best,\n                    "min_avg_rank_any_epoch": min(r["avg_rank"] for r in ours),\n                    "max_top1_any_epoch": max(r["top1"] for r in ours),\n                    "note": "final = honest unsupervised result; best = picked with the true pairs (upper bound)"})\njson.dump(summary, open(os.path.join(OUT, "summary.json"), "w"), indent=1)\n\nimport matplotlib\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\nname = f"{a.kind} {a.scheme if a.kind == \'ours\' else \'\'} seed {a.seed}".replace("  ", " ")\nfig, ax = plt.subplots(1, 2, figsize=(12, 4.5))\nif not native:\n    t = [r["train_hours"] for r in ours]\n    ax[0].plot(t, [r["top1"] for r in ours], color="tab:red", label="top-1 (our metric)")\n    ax[0].axhline(1 / len(X_eval), color="gray", ls="--", lw=1, label="random guess")\n    ax[0].set_ylabel(f"Top-1 accuracy ({len(X_eval):,} candidates)")\n    ax[1].plot(t, [r["avg_rank"] for r in ours], color="tab:blue", label="average rank (our metric)")\n    ax[1].axhline((len(X_eval) + 1) / 2, color="gray", ls="--", lw=1, label="random guess")\n    ax[1].set_ylabel(f"Average rank of the true vector (1 = perfect)")\n    ax[1].set_title(f"vec2vec {name}: average rank vs time")\nelse:\n    t = [r["train_hours"] for r in val]\n    ax[0].plot(t, [authors_top1(r) for r in val], color="tab:red", label="top-1 (authors\' validation)")\n    ax[0].set_ylabel("Top-1 accuracy (authors\' validation set)")\n    ax[1].plot([r["train_hours"] for r in ours], [r["epoch_minutes"] for r in ours], color="tab:green",\n               label="minutes per epoch")\n    ax[1].set_ylabel("Minutes per epoch")\n    ax[1].set_title(f"vec2vec {name}: speed")\nax[0].set_title(f"vec2vec {name}: top-1 vs time")\nfor x in ax:\n    x.set_xlabel(f"Training time (hours, {gpu})"); x.legend(); x.grid(alpha=0.3)\nplt.tight_layout(); plt.savefig(os.path.join(OUT, "curve.png"), dpi=130)\nprint("DONE", json.dumps(summary), flush=True)')

# Cell 6 - check inputs and download the models / texts once (so the two runs do not download at the same time)
os.makedirs("./_sandbox/phaseV/t3/working/runs", exist_ok=True)
kinds = {r["kind"] for r in RUNS}
if kinds & {"ours", "dpr_matched"}:
    need = ["bge-large_victim_L32.npy", "gtr_victim_L32.npy", "gtr_attextra_L32.npy"] + \
           (["texts_extra.json"] if "dpr_matched" in kinds else [])
    for f in need:
        hits = glob.glob(f"./_sandbox/phaseV/t2/data/**/{f}", recursive=True)
        assert hits, f"missing input {f}: Add Input -> Notebooks -> phaseA_fp32_embeddings and phaseA2b_verify_attacker_extra"
        print("found", hits[0])
if "dpr_matched" in kinds:
    from huggingface_hub import snapshot_download
    snapshot_download("BAAI/bge-large-en-v1.5")
if "native" in kinds:
    from datasets import load_dataset
    from sentence_transformers import SentenceTransformer
    t = time.time()
    ds = load_dataset("jxm/nq_corpus_dpr", split="train"); print(f"NQ DPR corpus: {len(ds):,} passages ({time.time()-t:.0f}s)")
    assert len(ds) >= 2 * 1_000_000 + 4096
    for m in ["infgrad/stella-base-en-v2", "thenlper/gte-base"]:
        SentenceTransformer(m, trust_remote_code=True); print("downloaded", m)
    del ds

# Cell 7 - start both runs (one per GPU) and print progress every 10 minutes. This is the long cell.
procs = []
for gpu, r in enumerate(RUNS):
    out = f"./_sandbox/phaseV/t3/working/runs/{r['name']}"
    os.makedirs(out, exist_ok=True)
    cmd = [sys.executable, "-u", "./_sandbox/phaseV/t3/working/code/v2v_job.py", "--kind", r["kind"], "--seed", str(r["seed"]),
           "--hours", str(0.05 if QUICK_TEST else BUDGET_HOURS[r["kind"]]), "--data", "./_sandbox/phaseV/t2/data",
           "--out", out, "--repo", "./_sandbox/phaseV/t3/working/vec2vec"]
    if r["kind"] == "native": cmd += ["--num_points", str(r["num_points"])]
    if QUICK_TEST: cmd += ["--smoke"]
    env = {**os.environ, "CUDA_VISIBLE_DEVICES": str(gpu)}
    procs.append((r, out, subprocess.Popen(cmd, env=env, stdout=open(f"{out}/stdout.txt", "w"), stderr=subprocess.STDOUT)))
    time.sleep(5)   # stagger the starts

def last_line(out):
    try:
        rows = [json.loads(l) for l in open(f"{out}/v2v_log.jsonl")]
    except FileNotFoundError:
        return "starting"
    ep = [x for x in rows if x["kind"] == "ours"]
    if not ep: return "setting up / first epoch"
    e = ep[-1]
    if "top1" in e:
        return (f"epoch {e['epoch']}  {e['train_hours']:.2f} h  top1 {e['top1']:.4f}  avg_rank {e['avg_rank']:.0f}"
                f"  (best rank so far {min(x['avg_rank'] for x in ep):.0f})")
    val = [x for x in rows if x["kind"] == "authors_val"]
    t1 = [v for k, v in val[-1].items() if k.startswith("val/stella_gte_top_1_acc")] if val else []
    return f"epoch {e['epoch']}  {e['train_hours']:.2f} h  authors' top-1 {t1[0] if t1 else float('nan'):.4f}"

t0 = time.time()
while any(p.poll() is None for _, _, p in procs):
    time.sleep(30 if QUICK_TEST else 600)
    print(f"--- {(time.time()-t0)/3600:.2f} h since start")
    for r, out, p in procs:
        state = "running" if p.poll() is None else f"ended (code {p.returncode})"
        print(f"  {r['name']:24s} {state:16s} {last_line(out)}")
for r, out, p in procs:
    if p.returncode != 0:
        why = " (killed from outside: usually out of memory)" if p.returncode in (-9, 137) else ""
        print(f"\n!!! {r['name']} FAILED with exit code {p.returncode}{why}. Last lines of its stdout.txt:")
        print("".join(open(f"{out}/stdout.txt").readlines()[-30:]))

# Cell 8 - results: verdict per run (rule fixed in cell 3) and the curves
display = print; Image = lambda p: p
rows = []
for r, out, p in procs:
    if not os.path.exists(f"{out}/summary.json"):
        rows.append({"run": r["name"], "status": "FAILED, see stdout.txt"}); continue
    s = json.load(open(f"{out}/summary.json"))
    if r["kind"] == "native":
        learned = (s["authors_val_top1_max"] or 0) >= 0.1
        rows.append({"run": r["name"], "hours": round(s["train_hours"], 2), "epochs": s["epochs"], "steps": s["steps"],
                     "authors_top1_last": s["authors_val_top1_last"], "authors_top1_max": s["authors_val_top1_max"],
                     "LEARNED": learned})
    else:
        learned = s["max_top1_any_epoch"] >= 0.01 or s["min_avg_rank_any_epoch"] <= (s["n_eval"] + 1) / 2 / 4
        rows.append({"run": r["name"], "hours": round(s["train_hours"], 2), "epochs": s["epochs"], "steps": s["steps"],
                     "min_per_epoch": round(s["minutes_per_epoch_median"], 2),
                     "top1_final": s["final"]["top1"], "avg_rank_final": round(s["final"]["avg_rank"]),
                     "top1_max": s["max_top1_any_epoch"], "avg_rank_min": round(s["min_avg_rank_any_epoch"]),
                     "LEARNED": learned})
import pandas as pd
